package org.apache.commons.math.stat;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.Comparator;
import java.util.Iterator;
import java.util.TreeMap;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.math.stat.Frequency#addValue(Object)
 */
public class Frequency_addValue_TriageGen0Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }

    @Test
    public void testAddValueWithInteger() {
        // Testing addValue(Object) where Object is an Integer (which is Comparable)
        frequency.addValue(Integer.valueOf(10));
        frequency.addValue(Integer.valueOf(10));
        frequency.addValue(Integer.valueOf(20));

        assertEquals(2L, frequency.getCount(10));
        assertEquals(1L, frequency.getCount(20));
        assertEquals(3L, frequency.getSumFreq());
    }

    @Test
    public void testAddValueWithLong() {
        // Testing addValue(Object) where Object is a Long
        frequency.addValue(Long.valueOf(100L));
        frequency.addValue(Long.valueOf(200L));

        assertEquals(1L, frequency.getCount(100L));
        assertEquals(1L, frequency.getCount(200L));
    }

    @Test
    public void testAddValueWithString() {
        // Testing addValue(Object) where Object is a String (which is Comparable)
        frequency.addValue("apple");
        frequency.addValue("banana");
        frequency.addValue("apple");

        assertEquals(2L, frequency.getCount("apple"));
        assertEquals(1L, frequency.getCount("banana"));
    }

    @Test(expected = ClassCastException.class)
    public void testAddValueWithNonComparable() {
        // Testing addValue(Object) where Object is NOT a Comparable
        // This should trigger a ClassCastException when casting to Comparable<?>
        class NonComparable {
            @Override
            public boolean equals(Object obj) {
                return super.equals(obj);
            }
        }
        frequency.addValue(new NonComparable());
    }

    @Test
    public void testAddValueWithNull() {
        // Testing addValue(Object) with null
        // Depending on implementation, this might throw NPE or handle null
        // Given the cast (Comparable<?>) v, null is a valid cast to Comparable
        frequency.addValue(null);

        assertEquals(1L, frequency.getCount(null));
        assertEquals(1L, frequency.getSumFreq());
    }

    @Test
    public void testAddValueConsistencyWithOtherTypes() {
        // Ensure the Object-based addValue produces same results as primitive-based addValue
        frequency.addValue(5); // uses addValue(int)
        frequency.addValue(Integer.valueOf(5)); // uses addValue(Object)

        assertEquals(2L, frequency.getCount(5));
        assertEquals(2L, frequency.getSumFreq());
    }
}
